/* Soil nitrogen as animated microsites, functional microbes and distinct exits. */
(()=>{'use strict';const TAU=Math.PI*2,C={organic:'#9cab6c',ammonium:'#d5b35c',nitrite:'#a7b487',nitrate:'#66aabc',ammonia:'#d49461',denit:'#a58aaf',water:'#8abfcf',earth:'#a99270'},L=(a,b,t)=>a+(b-a)*t;
function ellipse(w,x,y,z,rx,ry,c,alpha=.2){w.poly(Array.from({length:33},(_,i)=>[x+Math.cos(i/32*TAU)*rx,y+Math.sin(i/32*TAU)*ry,z]),c,{alpha,lit:false})}
function atom(w,p,r,c,alpha=1){w.dot(p,r,c,{alpha})}
function ion(w,p,kind,r=.065,alpha=1){const colors={NH4:C.ammonium,NH3:C.ammonia,NO2:C.nitrite,NO3:C.nitrate,N2:C.denit,N2O:C.denit,NO:C.denit,organic:C.organic,H2O:C.water,O2:'#a5c4d0',H:'#d8a28e'},color=colors[kind]||C.organic;atom(w,p,r,color,alpha);if(kind==='NH4'||kind==='NH3'||kind==='H2O'){const n=kind==='NH4'?4:kind==='NH3'?3:2;for(let j=0;j<n;j++){const a=kind==='H2O'?-.92+j*1.84:j/n*TAU+.25;atom(w,[p[0]+Math.cos(a)*r*.98,p[1]+Math.sin(a)*r*.98,p[2]-.015],r*.34,'#f1eddc',alpha)}}else if(['NO2','NO3','NO'].includes(kind)){const n=kind==='NO3'?3:kind==='NO2'?2:1;for(let j=0;j<n;j++){const a=j/n*TAU+.3;atom(w,[p[0]+Math.cos(a)*r*1.05,p[1]+Math.sin(a)*r*1.05,p[2]-.01],r*.42,'#d6a08b',alpha)}}else if(['N2','N2O','O2'].includes(kind)){const q=[p[0]+r*1.45,p[1]+r*.1,p[2]];w.line([p,q],color,1,{alpha});atom(w,q,r,color,alpha);if(kind==='N2O')atom(w,[q[0]+r*1.25,q[1]+r*.2,q[2]],r*.72,'#d6a08b',alpha)}}
function packets(w,points,count,kind,{speed=.12,size=.062,phase=0,alpha=1,water=false}={}){for(let i=0;i<count;i++){const t=(w.time*speed+i/count+phase)%1,p=w.pathPoint(points,t);if(water)atom(w,p,size*2.4,C.water,.22);ion(w,p,typeof kind==='function'?kind(t):kind,size,alpha)}}
function cell(w,x,y,z,{color='#88a77b',active=true,seed=0,length=.72}={}){const angle=Math.sin(seed*2.1)*.32,pulse=active?1+.035*Math.sin(w.time*2+seed):1,r=.17*pulse,n=12,m=12,map=(u,v,a)=>[x+u*Math.cos(angle)-v*Math.sin(angle),y+u*Math.sin(angle)+v*Math.cos(angle),z+a];for(let i=0;i<n;i++){const a=-Math.PI/2+i/n*Math.PI,b=-Math.PI/2+(i+1)/n*Math.PI;for(let j=0;j<m;j++){const u=j/m*TAU,v=(j+1)/m*TAU,P=(t,k)=>map(Math.sin(t)*length/2,Math.cos(t)*r*Math.cos(k),Math.cos(t)*r*Math.sin(k));w.poly([P(a,u),P(a,v),P(b,v),P(b,u)],active?color:'#9ca69a',{alpha:.88})}}const dna=Array.from({length:20},(_,i)=>map(-length*.27+i/19*length*.54,Math.sin(i*.85+seed)*.055,-r*.88));w.line(dna,active?'#d7e7b5':'#c7d1bc',1.1);for(let i=0;i<7;i++)atom(w,map((i-3)*length*.09,Math.cos(i*2)*.08,-r*.92),.017,'#c2d69e');const flag=Array.from({length:22},(_,i)=>{const t=i/21;return map(-length/2-t*.44,Math.sin(t*11-w.time*(active?2:.1)+seed)*.045,-.01)});w.line(flag,active?color:'#a6b1a0',.9);for(let i=0;i<4;i++){const u=(i-1.5)*length*.16;w.line([map(u,r*.83,0),map(u-.04,r*1.26,0)],'#a2bb86',.7)}}
function colony(w,x,y,z,{type='decomposer',active=true}={}){const color=type==='ammonia'?'#72a69d':type==='nitrite'?'#9bb37e':type==='denit'?'#a18bad':'#90a66b';ellipse(w,x,y,z+.12,.8,.42,color,.12);cell(w,x-.15,y+.05,z,{color,active,seed:1});cell(w,x+.29,y-.22,z+.08,{color,active,seed:4,length:.57});if(type==='decomposer')for(let j=0;j<3;j++){const path=Array.from({length:16},(_,i)=>{const t=i/15;return [x-1.1+t*.95,y+.05+Math.sin(t*5+j)*.1+j*.12,z+.1+j*.025]});w.line(path,'#d6d5b4',1.6);for(let k=4;k<14;k+=4){const p=path[k];w.line([p,[p[0]-.09,p[1]+.18,p[2]+.03],[p[0]-.22,p[1]+.21,p[2]+.05]],'#cecfad',1)}}}
function enzyme(w,x,y,z){for(let j=0;j<3;j++){const a=j/3*TAU;atom(w,[x+Math.cos(a)*.08,y+Math.sin(a)*.08,z],.09,'#bfcc8c',.9)}atom(w,[x,y,z-.04],.045,'#9fac71')}
function pool(w,x,y,z,kind,label){ellipse(w,x,y,z+.1,.47,.22,C.water,.22);for(let i=0;i<5;i++){const a=i*2.399+w.time*.09;ion(w,[x+Math.cos(a)*.3,y+Math.sin(a)*.13,z-.02],kind,.052)}w.label([x,y+.47,z],label,{size:13,pill:true,color:kind==='NH4'?'#99782f':'#4e8189'})}
function residue(w,x,y,z){for(let i=0;i<6;i++){const xx=x+Math.sin(i*2)*.45,yy=y+(i%2)*.08,zz=z+Math.cos(i*2)*.2;w.box(xx,yy,zz,.46,.06,.15,i%2?'#b19a6b':'#95865e');w.line([[xx-.18,yy+.065,zz],[xx+.18,yy+.065,zz]],'#ccb686',.7);ion(w,[xx,yy+.1,zz-.03],'organic',.045)}}
function sky(w,s){const ctx=w.ctx,W=w.width,H=w.height,loss=NitrogenMechanisms.activeLoss(s.step,s.lossMode),wet=loss==='leaching'||loss==='denitrification'&&s.anoxic,g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,wet?'#cddfe2':'#dcecf0');g.addColorStop(.47,'#f4f6ed');g.addColorStop(1,'#eaf0df');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);if(!wet){const sx=W*.83,sy=H*.15,r=Math.min(W,H)*.032,glow=ctx.createRadialGradient(sx,sy,r*.2,sx,sy,r*4.5);glow.addColorStop(0,'#eedba787');glow.addColorStop(1,'#f6e6b000');ctx.fillStyle=glow;ctx.fillRect(sx-r*5,sy-r*5,r*10,r*10);ctx.fillStyle='#ecd9a4';ctx.beginPath();ctx.arc(sx,sy,r,0,TAU);ctx.fill()}for(let j=0;j<2;j++){const x=W*(j?.64:.25)+Math.sin(w.time*.015+j)*W*.012,y=H*(j?.14:.18),width=W*(wet?.25:.2),height=width*.43;ctx.save();ctx.translate(x,y);ctx.scale(width,height);ctx.beginPath();ctx.moveTo(-.52,.18);ctx.bezierCurveTo(-.67,.06,-.58,-.27,-.36,-.24);ctx.bezierCurveTo(-.36,-.65,.08,-.73,.19,-.36);ctx.bezierCurveTo(.39,-.58,.65,-.29,.57,-.06);ctx.bezierCurveTo(.83,.03,.66,.33,.44,.31);ctx.bezierCurveTo(.28,.47,.13,.39,.06,.35);ctx.bezierCurveTo(-.11,.46,-.3,.38,-.34,.27);ctx.bezierCurveTo(-.46,.39,-.6,.3,-.52,.18);ctx.closePath();const cloud=ctx.createLinearGradient(0,-.6,0,.4);cloud.addColorStop(0,wet?'#f0f3ef':'#fffff8');cloud.addColorStop(.55,wet?'#c3d1d1':'#edf3ee');cloud.addColorStop(1,wet?'#a7b9be':'#d5e2e1');ctx.fillStyle=cloud;ctx.globalAlpha=wet?.87:.83;ctx.fill();ctx.clip();for(const [px,py,rr] of [[-.36,-.15,.26],[-.1,-.36,.31],[.2,-.14,.28],[.42,.02,.22],[-.13,.12,.23]]){const light=ctx.createRadialGradient(px-rr*.2,py-rr*.25,.01,px,py,rr);light.addColorStop(0,wet?'#f7faf259':'#fffffb9c');light.addColorStop(.65,'#ffffff1a');light.addColorStop(1,'#ffffff00');ctx.fillStyle=light;ctx.fillRect(px-rr,py-rr,rr*2,rr*2)}ctx.restore()}if(w.canvas)w.canvas.dataset.skyRendering='soft-cumulus'}
function roots(w,x,y,z){for(let i=0;i<8;i++){const a=i/8*TAU,path=Array.from({length:14},(_,j)=>{const t=j/13;return [x+Math.cos(a)*(.08+.85*t),y-1.78*t,z+Math.sin(a)*.5*t]});w.line(path,'#e1d0a8',1.25);for(let j=4;j<13;j+=3){const p=path[j];w.line([p,[p[0]+Math.cos(a+.6)*.18,p[1]-.15,p[2]+Math.sin(a+.6)*.12]],'#e8dbb9',.65)}}}
function base(w,s){w.box(0,-3.5,0,11.4,.13,5.6,'#b6a480');w.box(0,-3.35,1.55,11.1,3.35,.25,'#ab926b');w.box(-5.5,-3.35,.15,.15,3.35,2.8,'#b09b76');w.box(5.5,-3.35,.15,.15,3.35,2.8,'#b09b76');w.box(0,.01,1.15,11.2,.07,1.05,'#9eaf77');for(let i=0;i<120;i++){const x=-5.2+(i*1.719)%10.4,y=-3.1+(i*.433)%2.9,r=.025+(i%4)*.008;w.poly([[x-r,y-r,1.38],[x+r,y-r*.5,1.38],[x+r*.6,y+r,1.38],[x-r*.7,y+r*.6,1.38]],['#8c7551','#c1aa82','#9a805b'][i%3],{lit:false,layer:-100})}for(let i=0;i<12;i++)ellipse(w,-4.9+(i*.937)%9.5,-2.9+(i*.617)%2.7,1.36,.12+(i%3)*.045,.065,'#756947',.3);for(let i=0;i<5;i++)w.leaf([-4.8+i*.25,.1,.7],[-4.45+i*.25,.13,.95],.1,'#b7a16b');w.plant(3.5,.07,.28,2.1,1);w.plant(4.5,.07,1.05,1.5,3);roots(w,3.5,.06,.28);w.line([[-5.3,s.e.rootBoundary,-1.35],[5.2,s.e.rootBoundary,-1.35]],'#a6baa5',1,{dash:[6,5]});w.label([-4.25,s.e.rootBoundary-.08,-1.4],'根层下界 · 示意',{size:10,pill:true});w.label([-4.0,-3.08,-1.0],'微生物、离子均为放大示意',{size:10,color:'#7d896f'});}
function clay(w){const x=-3.15,y=-1.55,z=-.55;for(let i=0;i<3;i++)w.box(x,y+i*.09,z,.95,.035,.45,'#8c9e9b');for(let i=0;i<4;i++){ion(w,[x-.34+i*.23,y+.38,z-.22],'NH4',.045);w.label([x-.34+i*.23,y+.19,z-.25],'−',{size:10,color:'#6a8580'})}w.label([x,y-.23,z],'交换位点吸附 NH₄⁺',{size:10,pill:true})}
function urea(w,s){const y=s.incorporated?-.65:.13,x=-2.2,z=-.25;for(let i=0;i<7;i++)atom(w,[x+Math.sin(i*2.4)*.29,y,z+Math.cos(i*2.4)*.17],.045,'#eee9cf');w.label([x,y+.28,z],s.incorporated?'尿素 · 混入土层':'尿素 · 表施',{size:11,pill:true});return [x,y,z]}
function overview(w){residue(w,-4.15,-.7,-.35);colony(w,-2.95,-.8,-.3);pool(w,-.75,-.8,-.4,'NH4','NH₄⁺');colony(w,.8,-.8,-.35,{type:'nitrite'});pool(w,2.2,-.8,-.45,'NO3','NO₃⁻');packets(w,[[-4,-.6,-.4],[-2.8,-.7,-.4],[-.7,-.8,-.4]],10,t=>t<.48?'organic':'NH4',{speed:.09});packets(w,[[-.5,-.85,-.4],[.7,-.8,-.4],[2.3,-.8,-.4]],10,t=>t<.4?'NH4':t<.7?'NO2':'NO3',{speed:.09,phase:.2});w.label([-2.55,-1.55,-.4],'分解 · 矿化',{size:12,pill:true});w.label([.7,-1.55,-.4],'氧化 · 硝化',{size:12,pill:true})}
function mineralization(w){residue(w,-4.2,-.68,-.35);colony(w,-2.8,-.8,-.35);for(let i=0;i<3;i++)enzyme(w,-3.6+Math.sin(w.time*.7+i)*.1,-.58-i*.12,-.45);pool(w,.4,-.8,-.4,'NH4','释放 NH₄⁺');packets(w,[[-4,-.6,-.4],[-3.6,-.55,-.4],[-2.7,-.8,-.4],[-1,-.8,-.4],[.5,-.8,-.4]],14,t=>t<.46?'organic':'NH4',{speed:.08});packets(w,[[.3,-1,-.4],[-1.2,-1.35,-.4],[-2.65,-.95,-.4]],5,t=>t<.72?'NH4':'organic',{speed:.065,size:.047});w.label([-4.05,-.1,-.35],'含氮残体',{size:12,pill:true});w.label([-3.5,-1.32,-.4],'菌丝与胞外酶接触残体',{size:11,pill:true});w.label([-.3,-1.65,-.4],'微生物同化：一部分氮暂存于菌体',{size:11,pill:true});w.label([-.9,.65,-.3],'有机氮分解 → 氨化 → 铵态氮',{size:14,pill:true})}
function hydrolysis(w,s){const p=urea(w,s);colony(w,-3.7,-.75,-.4);for(let i=0;i<3;i++)enzyme(w,p[0]-.15+i*.22,p[1]-.2,-.3);ellipse(w,p[0],p[1],-.15,.6,.2,C.water,.15);pool(w,.5,-.85,-.4,'NH4','NH₄⁺ / NH₃');packets(w,[p,[-1.8,p[1]-.1,-.3],[-.8,-.6,-.4],[.5,-.85,-.4]],12,t=>t<.3?'organic':'NH4',{speed:.1});packets(w,[[-1.3,1.1,-.4],[-1.5,.35,-.4],[-2.1,p[1],-.4]],4,'H2O',{size:.035});w.label([-1.0,-1.55,-.4],'脲酶参与水解，施肥点 pH 可短时升高',{size:12,pill:true});w.label([-3.65,-1.38,-.4],'脲酶可来自微生物、植物残体等',{size:10,pill:true})}
function nitrification(w){pool(w,-4.3,-.8,-.4,'NH4','NH₄⁺');colony(w,-2.4,-.85,-.4,{type:'ammonia'});pool(w,-.6,-.8,-.4,'NO2','NO₂⁻');colony(w,.95,-.85,-.4,{type:'nitrite'});pool(w,2.5,-.8,-.4,'NO3','NO₃⁻');packets(w,[[-4.2,-.8,-.48],[-2.4,-.8,-.48],[-.6,-.8,-.48],[.95,-.8,-.48],[2.5,-.8,-.48]],16,t=>t<.3?'NH4':t<.78?'NO2':'NO3',{speed:.085});for(const x of [-2.4,.95]){packets(w,[[x,1,-.4],[x,.2,-.4],[x,-.8,-.4]],5,'O2',{speed:.09,size:.045});w.label([x,.65,-.4],'O₂ 进入好氧微区',{size:10,pill:true});}w.label([-2.4,-1.55,-.4],'氨氧化微生物',{size:11,pill:true});w.label([.95,-1.55,-.4],'亚硝酸氧化微生物',{size:11,pill:true});packets(w,[[-2.2,-1.1,-.5],[-1.9,-1.65,-.5],[-1.5,-2.15,-.5]],5,'H',{speed:.1,size:.038});w.label([-1.3,-2.15,-.5],'释放 H⁺ · 酸化贡献',{size:10,pill:true})}
function retention(w){pool(w,-.5,-.75,-.4,'NH4','NH₄⁺');pool(w,1.45,-.9,-.45,'NO3','NO₃⁻');clay(w);colony(w,-2,-.7,-.3);packets(w,[[-.5,-.75,-.45],[1.3,-1.3,-.25],[3.0,-1.0,.1],[3.5,.35,.28],[3.5,1.75,.28]],11,t=>t>.72?'organic':'NH4',{speed:.09,size:.045});packets(w,[[1.45,-.9,-.5],[2.4,-1.3,-.15],[3.5,-.2,.28],[3.5,1.65,.28]],9,t=>t>.64?'organic':'NO3',{speed:.1,size:.045});packets(w,[[-.5,-1,-.4],[-1.2,-.95,-.4],[-2,-.7,-.4]],5,t=>t>.78?'organic':'NH4',{speed:.075,size:.045});w.label([3.1,1.3,.1],'进入根系与植株',{size:12,pill:true});w.label([-.1,-1.7,-.5],'吸收 / 吸附 / 微生物同化',{size:11,pill:true})}
function ammonia(w,s){const p=urea(w,s),origin=[p[0]+.5,p[1]-.03,-.35],count=Math.max(1,Math.round(22*s.e.visualEscape));pool(w,p[0]-.6,p[1]-.42,-.4,'NH4','溶液 NH₄⁺');for(let i=0;i<3;i++)enzyme(w,p[0]+i*.16,p[1]-.2,-.4);packets(w,[[p[0]-.55,p[1]-.4,-.45],origin],5,'NH3',{speed:.1,size:.05});w.label([origin[0]+.6,origin[1],-.35],'NH₃(aq)',{size:11,pill:true});for(let i=0;i<count;i++){const t=(w.time*(s.incorporated?.055:.12)+i/count)%1,x=origin[0]+3*t+.12*Math.sin(t*9+i),y=L(origin[1],2.9,t),z=-.4+.12*Math.sin(t*6+i);ellipse(w,x,y,z+.06,.13+t*.06,.1+t*.08,C.ammonia,.11*(1-t));ion(w,[x,y,z],'NH3',.055,1-t*.7)}for(let i=0;i<3;i++){const y=1+i*.48;w.line(Array.from({length:16},(_,j)=>{const t=j/15;return [-.3+t*2.0,y+.05*Math.sin(t*6+w.time),-.4]}),'#b5c0b3',.7,{alpha:.5})}w.label([1.3,2.75,-.35],'NH₃(g) 扩散进入空气',{size:12,pill:true,color:'#ab7b49'});w.label([-4.1,1.0,-.3],`施肥点 pH ${s.pH.toFixed(1)}`,{size:12,pill:true});if(s.incorporated){packets(w,[origin,[-1.5,-.8,-.4],[-3,-1.2,-.4]],6,'NH4',{speed:.055,size:.04});clay(w);w.label([-1.3,-1.7,-.4],'混入土层：增加滞留与缓冲机会',{size:11,pill:true})}}
function rain(w){for(let i=0;i<36;i++){const t=(w.time*.52+i/36)%1,x=-4+(i*.619)%6,z=-.8+(i*.271)%1.2,y=3.2-t*3.1;atom(w,[x,y,z],.018,C.water,.7);w.line([[x,y+.08,z],[x-.025,y+.18,z]],'#accdd7',.8,{alpha:.5})}}
function waterBody(w,points){const n=36,sides=8,rings=[];for(let i=0;i<=n;i++){const p=w.pathPoint(points,i/n),r=.075+.02*Math.sin(i*.5+w.time);rings.push(Array.from({length:sides},(_,j)=>[p[0]+Math.cos(j/sides*TAU)*r,p[1],p[2]+Math.sin(j/sides*TAU)*r]))}for(let i=0;i<n;i++)for(let j=0;j<sides;j++)w.poly([rings[i][j],rings[i+1][j],rings[i+1][(j+1)%sides],rings[i][(j+1)%sides]],C.water,{alpha:.16,lit:false})}
function beaker(w,x,y,z,level){const r=.47,h=.9,n=28;for(let i=0;i<n;i++){const a=i/n*TAU,b=(i+1)/n*TAU;w.poly([[x+Math.cos(a)*r,y,z+Math.sin(a)*r],[x+Math.cos(b)*r,y,z+Math.sin(b)*r],[x+Math.cos(b)*r,y+h,z+Math.sin(b)*r],[x+Math.cos(a)*r,y+h,z+Math.sin(a)*r]],'#bdd6cc',{alpha:.15})}w.line(Array.from({length:n+1},(_,i)=>[x+Math.cos(i/n*TAU)*r,y+h,z+Math.sin(i/n*TAU)*r]),'#aacbc5',1.3);if(level)w.cylinder(x,y+.02,z,r*.94,level,C.water,{alpha:.35,n:26})}
function leaching(w,s){rain(w);clay(w);pool(w,.7,-.8,-.65,'NO3','溶解态 NO₃⁻');const path=s.drainage?[[.75,.06,-.65],[.85,-.75,-.65],[1.05,-1.65,-.65],[1.2,-2.35,-.65],[1.8,-2.85,-.65],[5.45,-3.05,-.65],[6.05,-3.15,-.65]]:[[.75,.06,-.65],[.85,-.75,-.65],[1.05,-1.6,-.65]];waterBody(w,path);packets(w,path,12,'NO3',{speed:.1,size:.04,water:true});for(let i=0;i<12;i++){const f=(w.time*.15+i/12)%1;atom(w,[-2.8+(i%3)*.32,-.2-f*(s.drainage?2.5:1.2),-.5],.035,C.water,.25)}beaker(w,6.05,-3.8,-.65,s.drainage?.34:0);if(s.drainage){for(let i=0;i<6;i++)ion(w,[6.05+Math.sin(i*2)*.27,-3.53,-.65+Math.cos(i*2)*.23],'NO3',.033);w.label([5.95,-2.8,-.65],'含 NO₃⁻ 的渗漏液',{size:11,pill:true});w.label([1.4,-2.05,-.7],'随水越过根层',{size:11,pill:true})}else w.label([5.6,-2.85,-.65],'尚未形成淋洗出口',{size:11,pill:true});}
function denitrification(w,s){const active=s.e.denitrificationActive;residue(w,-3,-.95,-.45);colony(w,-.75,-.9,-.45,{type:'denit',active});pool(w,1.35,-.9,-.5,'NO3','NO₃⁻');if(s.anoxic){w.box(0,.08,.6,10,.055,1.7,C.water,{alpha:.2});w.label([-.65,.65,-.45],'积水 · 缺氧微区',{size:12,pill:true})}else{packets(w,[[-.5,1,-.4],[-.6,.2,-.4],[-.75,-.9,-.45]],5,'O2',{size:.05});w.label([-.6,.65,-.45],'氧气较充足',{size:12,pill:true})}if(active){packets(w,[[1.3,-.9,-.55],[.45,-.85,-.55],[-.75,-.9,-.55]],7,'NO3',{speed:.09});packets(w,[[-3,-.85,-.5],[-1.9,-.85,-.5],[-.75,-.9,-.55]],6,'organic',{speed:.09});const path=[[-.75,-.9,-.6],[.2,-.75,-.6],[1.25,-.2,-.6],[1.9,1.1,-.6],[2.2,2.8,-.6]];packets(w,path,12,t=>t<.18?'NO2':t<.36?'NO':t<.68?'N2O':'N2',{speed:.085,size:.065});for(let i=0;i<5;i++){const t=(w.time*.14+i/5)%1;ellipse(w,1.7+t*.55,.1+t*2.4,-.5,.16+t*.05,.11+t*.06,C.denit,.12*(1-t))}w.label([2.1,2.7,-.6],'N₂O / N₂ 逸出',{size:13,pill:true,color:'#9274a4'});w.label([-.3,-1.7,-.6],'NO₃⁻ → NO₂⁻ → NO → N₂O → N₂',{size:12,pill:true})}else w.label([.1,-1.7,-.55],s.anoxic?'缺少可用有机碳，路径弱化':'有氧条件下，该路径弱化',{size:12,pill:true});w.label([-3,-.25,-.45],s.carbon?'可用有机碳':'缺少可用有机碳',{size:11,pill:true});}
function draw(w,s){base(w,s);const loss=NitrogenMechanisms.activeLoss(s.step,s.lossMode);if(loss==='volatilization')ammonia(w,s);else if(loss==='leaching')leaching(w,s);else if(loss==='denitrification')denitrification(w,s);else if(s.step===1)mineralization(w);else if(s.step===2)hydrolysis(w,s);else if(s.step===3)nitrification(w);else if(s.step===4)retention(w);else overview(w);if(w.canvas){w.canvas.dataset.nitrogenVisual='microbes-reaction-molecules';w.canvas.dataset.microbeMode=loss==='denitrification'?(s.e.denitrificationActive?'denitrification-active':'denitrification-limited'):s.step===1?'decomposers-enzymes':s.step===3?'ammonia-and-nitrite-oxidizers':'soil-microsites'}}
window.NitrogenWorld={draw,sky,cell,ion,packets};
})();
